def main():
    for ligne in LIGNES:
        assert len(ligne) == len(COLONNES), (ligne[0], ligne[2], len(ligne))
    with open(SORTIE, "w", encoding="utf-8", newline="") as f:
        w = csv.writer(f, quoting=csv.QUOTE_ALL)
        w.writerow(COLONNES)
        w.writerows(LIGNES)
    print(f"{len(LIGNES)} lignes écrites dans {os.path.normpath(SORTIE)}")


if __name__ == "__main__":
    main()
